      "achados": [
        {
          "proposicao": "No estudo de Pre-FEED de um sistema de produção offshore da Bacia de Santos, a especificação da planta de processamento primário foi tratada em conjunto com a avaliação do sistema de geração de energia.",
          "trechos": [
            "E26db318bd183666c:0:699",
            "E26db318bd183666c:699:1397"
          ],
          "condicoes": [
            "estudo aplicado a um caso de produção offshore",
            "fluido descrito como essencialmente gás e condensado",
            "fase de definição de arranjo produtivo"
          ],
          "limites": [
            "não apresenta requisito normativo de redundância, reserva girante ou N+1",
            "resultado ligado a um estudo de caso, não universal"
          ]
        },
        {
          "proposicao": "A avaliação da geração foi feita por modelagem em regime estacionário da unidade de produção e por construção de um sistema termodinâmico em ciclo Brayton integrado à planta de processo.",
          "trechos": [
            "E26db318bd183666c:699:1397"
          ],
          "condicoes": [
            "simulações em diferentes set points de temperatura e pressão",
            "uso de software de modelagem sequencial"
          ],
          "limites": [
            "o trecho não descreve comportamento transitório, recomposição, black start, load shedding ou compartilhamento de carga",
            "não informa critérios de seleção entre números de turbinas além da viabilidade do caso"
          ]
        },
        {
          "proposicao": "Os resultados indicaram viabilidade técnica de geração elétrica para o campo estudado, com potência total e quantidade de turbinas não recuperáveis porque os números foram suprimidos, usando apenas fração da produção de gás natural.",
          "trechos": [
            "E26db318bd183666c:1397:2097"
          ],
          "condicoes": [
            "condições do campo de petróleo em relação à produção de condensado e gás natural",
            "estudo de caso proposto"
          ],
          "limites": [
            "valores de potência, número de turbinas e fração de gás estão apagados",
            "não há evidência de atendimento a demanda máxima, reserva girante ou contingência de perda de unidade"
          ]
        }
      ]
    },
    {
